contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // amount: Ether forwarded to c.play
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // observe before-state
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        bool reverted;
        // call play and capture revert
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;

        // General rule:
        // - If called with any value != TICKET_AMOUNT it must revert and leave pot unchanged.
        // - If called with exactly TICKET_AMOUNT it must not increase pot by more than TICKET_AMOUNT.
        // (Both cases allow other allowed transfers that reduce pot, so we only assert upper-bound on increase.)
        assert( (amount != 10 && reverted && potAfter == potBefore)
                || (amount == 10 && !reverted && potAfter <= potBefore + amount)
                || (amount == 10 && reverted && potAfter == potBefore) );
    }

    receive() external payable {}
}

